&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;air&lt;/a&gt;]&#160;; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;Dru&lt;/a&gt; 1, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag&lt;/a&gt; 1, &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;Occ&lt;/a&gt; 1, &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html&quot; title=&quot;Le spirite&quot;&gt;Spi&lt;/a&gt; 1&lt;br/&gt;
&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 1 minute&lt;br/&gt;
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V, G&lt;/a&gt;&lt;br/&gt;
&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#PORTEE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;contact&lt;/a&gt;&lt;br/&gt;
&lt;b&gt;Zone&lt;/b&gt; &#233;manation immobile dans un rayon de 3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)&lt;br/&gt;
&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 heure/&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt;&lt;br/&gt;
&lt;b&gt;Jet de sauvegarde&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#JETSDESAUVEGARDE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;annule&lt;/a&gt;&#160;; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;br /&gt;&lt;br /&gt;Le personnage augmente ou r&#233;duit subtilement les effets des vents naturels de la zone d&#39;effet du sort, qui se trouve &#234;tre une &#233;manation immobile centr&#233;e sur le point cibl&#233; au moment du lancer du sort. Dans cette zone, l&#39;effet des vents naturels (mais pas des vents magiques) est r&#233;duit ou augment&#233; d&#39;un niveau d&#39;intensit&#233; (voir &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Climat#Vents_4.html&quot; title=&quot;Les vents&quot;&gt;Les vents&lt;/a&gt;&quot;). Le niveau de force de vent maximum que le personnage peut modifier d&#233;pend de son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;, comme indiqu&#233; dans la table suivante. &lt;i&gt;Modification des vents&lt;/i&gt; n&#39;a aucun effet sur un vent magique.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Niveau de lanceur de sorts&lt;/td&gt;&lt;td&gt;Force du vent&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td CLASS=&quot;centre&quot;&gt;1-3 &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;L&#233;ger&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;centre&quot;&gt;4-9 &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;mod&#233;r&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;centre&quot;&gt;10-15 &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;fort&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;centre&quot;&gt;16 ou plus &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;violent&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
